We assume throughout that $f: \R^d \to \R$ is a differentiable function with $C_L$-Lipschitz continuous gradient,\footnote{We comment on the necessity of this global Lipschitz continuity in Remark~\ref{rem:Lip1} and Remark~\ref{rem:Lip2} below.} for some constant $C_L \ge 0$, such that $\inf_{x \in \R^d} f(x)=0$. 
Let $(\Omega, (\mathcal F_{n})_{n \in \N_0}, \mathcal F, \P)$ be a filtered probability space and let $(X_n)_{n \in \N_0}$, $(V_n)_{n \in \N_0}$ be $(\mathcal F_n)_{n \in \N_0}$-adapted processes satisfying for all $n \in \N_0$
\begin{align}\begin{split} \label{eq:MSGDintro}
		X_{n+1} &= X_n + \gamma_{n+1}V_{n+1}, \\
		V_{n+1}&= V_n - \gamma_{n+1}\mu V_n -\gamma_{n+1}\nabla f(X_n) + \gamma_{n+1} D_{n+1},
	\end{split}
\end{align}

Let $a,b >0$ and let $(E_n)_{n \in \N_0}$ be the $(\cF_n)_{n \in \N_0}$-adapted stochastic process given by
\begin{align} \label{eq:Lyapunov}
	E_n = a f(X_{n}) + \langle \grad f (X_{n}), V_n \rangle +\frac{b}{2} |V_n|^2.
\end{align}

statement.raw_tex:
\begin{theorem} \label{theo2}
	Set $\kappa = \frac{C_L}{L}$. Let 
	\begin{align*}
		\mu \in 
		\begin{cases}
			\bigl[\frac{1}{\sqrt 8}\bigl(5-\sqrt{ 9 - 8\kappa}\bigr)\sqrt{L},\frac{1}{\sqrt 8}\bigl(5+\sqrt{ 9 - 8\kappa}\bigr)\sqrt{L} \, \bigr], & \text{ if } \kappa < \frac 98, \\
			\bigl\{(2\sqrt \kappa-\sqrt{\kappa-1})\sqrt L \bigr\}, & \text{ if } \kappa \ge \frac 98.
		\end{cases}
	\end{align*}
	Then, under the assumptions of Theorem~\ref{theo1}, for every $\eps>0$ there exist $C, \bar \gamma\ge 0$ such that if $\sup_{n \in \N}\gamma_n \le \bar \gamma$ it holds that
	\begin{align*}
		\E[\1_{\IA_{n-1}} f(X_n)] \le C \exp(-(m-\eps)t_n), \quad \text{ for all } n \in \N,
	\end{align*}
	where  
	$$
	m = 
	\begin{cases} \sqrt{2L},& \text{ if } \kappa<\frac{9}{8},\\
		2(\sqrt{\kappa}-\sqrt{\kappa-1})\sqrt{L},& \text{ if } \kappa \ge \frac 98.
	\end{cases}
	$$
\end{theorem}

