proof.raw_tex:
\begin{lemma} \label{rem:Lipschitz}
	Let $r>0$, $y \in \R^d$ and assume that $\grad f$ is $C_L$-Lipschitz continuous on $B_r(y)$ and $\inf_{x \in B_r(y)}f(x)=f(y)$. Then, for all $x \in B_{r/2}(y)$ it holds that
	\begin{align} \label{eq:inversePL}
		|\grad f(x)|^2 \le 2 C_L (f(x)-f(y)).
	\end{align}
\end{lemma}

\begin{proof}
	Since $y$ is a critical point of $f$ we have for all $x \in B_{r/2}(y)$
	$$
	|\grad f(x)| = |\grad f(x)-\grad f(y)| \le \frac{C_L r}{2}.
	$$
	If $\grad f(x)=0$ the statement is obviously true. 
	If $\grad f(x) \neq 0$ consider the function 
	$$
	g(t) = f\Bigl(x-t \frac{\grad f(x)}{|\grad f(x)|}\Bigr).
	$$
	Note that for $x \in B_{r/2}(y)$ and all $t \in [0, \frac{|\grad f(x)|}{C_L}]$ we have $x-t \frac{\grad f(x)}{|\grad f(x)|} \in B_r(y)$ so that with the Lipschitz continuity of $\grad f$ and since $y$ is a local minimum
	\begin{align*}
		f(y)-f(x) &\le g\Bigl(\frac{|\grad f(x)|}{C_L}\Bigr)-g(0) = \int_0^{\frac{|\grad f(x)|}{C_L}} g'(s)  \, ds \\
		& \le \frac{|\grad f(x)|}{C_L} g'(0) +\frac{|\grad f(x)|^2}{2C_L}= -\frac{|\grad f(x)|^2}{2C_L}.
	\end{align*}
\end{proof}

\begin{lemma} \label{lem:Epositive}
	Let $a, b, C_L>0$ and
	\begin{align*}
		E(x,y) = a f(x) + \langle \grad f(x), y \rangle + \frac{b}{2} |y|^2.
	\end{align*}
	If $ab\ge C_L$ then for all $x \in \R^d$ satisfying $2C_L f(x)\ge |\grad f(x)|^2$ we have $E(x,y)\ge 0$, for all $y \in \R^d$.
\end{lemma}

\begin{proof}
	If $\grad f(x)=0$ the statement is trivial. If $\grad f(x) \neq 0$, we denote $\rho=\frac{|y|}{|\grad f(x)|}$ and get
	$$
	E(x,y) \ge \Bigl(\frac{a}{2C_L}-\rho+\frac{b}{2}\rho^2 \Bigr) |\grad f(x)|^2.
	$$
	The quadratic function $\varphi(\rho)=\frac{a}{2C_L}-\rho+\frac{b}{2}\rho^2$ attains its global minimum at $\rho=\frac{1}{b}$ and using $ab \ge C_L$ we deduce that
	\begin{align*}
		\varphi\Bigl(\frac 1b\Bigr)=\frac{a}{2C_L}-\frac{1}{2b}\ge 0.
	\end{align*}
\end{proof}

\begin{proposition} \label{prop:SHB}
	Let $L,a,b>0, \sigma \ge 0$. Let $(\IA_n)_{n \in \N_0}$ be a decreasing sequence of events such that, for all $n \in \N_0$, $\IA_n \in \cF_n$ and on $\IA_n$ it holds that
	\begin{align} \label{eq:1293182}
		|\grad f(X_n)|^2 \ge 2L f(X_n) \quad \text{and} \quad \E[|D_{n+1}|^2 | \cF_n] \le \sigma f(X_n).
	\end{align}
	Let $(\alpha_n)_{n \in \N}, (\beta_n)_{n \in \N}, (\delta_n)_{n \in \N}$ and $(\epsilon_n)_{n \in \N}$ be given by $\eqref{eq:alpha}$. Assume that $(\beta_n)_{n \in \N}$, $(\alpha_{n+1}-a\delta_{n+1}+2\beta_{n+1}L)_{n \in \N_0}$, $(\epsilon_{n+1}-\frac{b}{2} \delta_{n+1})_{n \in \N_0}$ and $(\frac{C_L}{2} \gamma_{n}^2- \frac{b}{2}\gamma_{n})_{n \in \N_0}$ are sequences of non-positive reals and $(\delta_n)_{n \in \N}$ is a sequence of non-negative reals.
	Moreover, if $\P(\bigcap_{n \in \N_0} \IA_n)<\P(\IA_0)$ additionally assume that $ab \ge C_L$.
	Then, for all $n \in \N$ it holds that
	\begin{align}\begin{split} \label{eq:238477}
			& \E[\1_{\IA_{n-1}} f(X_{n})]\le \Bigl(\prod_{i=1}^{n} (1+a\gamma_{i})^{-1}\Bigr) \\
			& \qquad \qquad \qquad \Bigl( \E[\1_{\IA_0} f(X_0)] + \sum_{i=1}^{n}  \frac{\gamma_{i}}{1+a\gamma_{i}} \Bigl(\prod_{j=1}^{i} (1+a\gamma_{j})\Bigr) \Bigl(\prod_{j=1}^{i}\delta_{j} \Bigr)\E[\1_{\IA_0}E_0] \Bigr).
		\end{split} 
	\end{align}	
\end{proposition}

\begin{proof}
	In a first step, we derive a convergence rate for the expectation of the Lyapunov process $(E_n)_{n \in \N_0}$. For this, we consider the time evolution of the three summands in \eqref{eq:Lyapunov}, separately.
	
	First, we look at the evolution of $(f(X_{n}))_{n \in \N_0}$.
	Let $x,y \in \R^d$ and note that with the Lipschitz-continuity of $\grad f$ we get
	\begin{align}
		\begin{split}
			\label{eq:Taylorp1}
			f(y)&\le f(x) + \langle \grad f(x),y-x\rangle  + \frac{C_L}{2} |y-x|^2.
		\end{split}
	\end{align}
	
	Now, for $n \in \N_0$ we use \eqref{eq:Taylorp1} with $x=X_{n}$ and $y=X_{n+1}$ and \eqref{eq:MSGDintro} to get 
	\begin{align} \begin{split} 
			\label{eq:273856230}
			&\E[\1_{\IA_n}f(X_{n+1})]\le \E\Big[\1_{\IA_n}\bigl(f(X_{n})-\gamma_{n+1}^2 |\grad f(X_n)|^2 \\
			&\qquad \qquad \qquad \qquad \quad + (\gamma_{n+1}-\gamma_{n+1}^2\mu) \langle \grad f(X_{n}),V_n\rangle + \frac{C_L}{2} \gamma_{n+1}^2 \bigl|V_{n+1}\bigr|^2 \bigr) \Big].
		\end{split}
	\end{align}
	
	Next, we control the evolution of $(|V_n|^2)_{n \in \N_0}$. Using \eqref{eq:1293182}, we get
	\begin{align} \begin{split}
			\E[\1_{\IA_n}|V_{n+1}|^2]
			\le  \E[\1_{\IA_n}(&(1-2\gamma_{n+1}\mu+\gamma_{n+1}^2\mu^2)|V_n|^2+ \gamma_{n+1}^2 |\grad f(X_n)|^2  \\
			&  - 2 (\gamma_{n+1}-\gamma_{n+1}^2\mu) \langle V_n, \grad f(X_n)\rangle  + \gamma_{n+1}^2 \sigma f(X_n))].
		\end{split}
	\end{align}
	Lastly,
	\begin{align} \begin{split} \label{eq:1764443}
			\E[\1_{\IA_n} &\langle \grad f(X_{n+1}), V_{n+1} \rangle] = \E[ \1_{\IA_n} (\langle \grad f(X_{n}), V_{n+1} \rangle + \langle \grad f(X_{n+1})- \grad f(X_{n}), V_{n+1} \rangle )] \\
			&\le \E[\1_{\IA_n} ((1-\gamma_{n+1}\mu) \langle \grad f(X_n), V_n \rangle - \gamma_{n+1}  |\grad f(X_n)|^2 + C_L \gamma_{n+1} |V_{n+1}|^2)].
		\end{split}
	\end{align}
	
	Combining the estimates \eqref{eq:273856230}-\eqref{eq:1764443}, we obtain
	\begin{align*}
		&\E[\1_{\IA_{n}} E_{n+1}] \\
		&\le \E[\1_{\IA_{n}}(\alpha_{n+1} f(X_n) + \beta_{n+1} |\grad f(X_n)|^2 +\delta_{n+1} \langle \grad f(X_n),V_n \rangle + \epsilon_{n+1} |V_n|^2)],
	\end{align*}
	where
	\begin{align} \label{eq:alpha}
		\begin{split}
			\alpha_{n+1} = &a + \Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr)\gamma_{n+1}^2 \sigma, \\
			\beta_{n+1} = &- \gamma_{n+1} - a\gamma_{n+1}^2 + \Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr)\gamma_{n+1}^2,\\
			\delta_{n+1} = &1-\mu\gamma_{n+1}+ a(\gamma_{n+1}-\gamma_{n+1}^2\mu) \\
			&- 2\Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr) (\gamma_{n+1}-\gamma_{n+1}^2\mu), \\
			\epsilon_{n+1} = &\Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr) (1-2\gamma_{n+1}\mu+\gamma_{n+1}^2\mu^2).
		\end{split}
	\end{align}
	By definition
	$
	\E[\1_{\IA_n} \langle \grad f(X_n), V_n \rangle ] =  \E[\1_{\IA_n}(E_n -a f(X_n)-\sfrac{b}{2} |V_n|^2)],
	$
	so that, using the PL-inequality \eqref{eq:1293182} and the fact that $(\beta_n)_{n \in \N}$ is non-positive, we get 
	\begin{align} \begin{split} \label{eq:579999663}
			&\E[\1_{\IA_{n}}E_{n+1}] \\
			&\le \E[\1_{\IA_n}(\delta_{n+1}E_n + (\alpha_{n+1}-a\delta_{n+1}+2\beta_{n+1}L) f(X_n)  + (\epsilon_{n+1}-\frac{b}{2} \delta_{n+1}) |V_n|^2)].
		\end{split}
	\end{align}
	With the assumptions on $(\alpha_{n+1}-a\delta_{n+1}+2\beta_{n+1}L)_{n \in \N_0}$ and $(\epsilon_{n+1}-\frac{b}{2} \delta_{n+1})_{n \in \N_0}$ we have
	$
	\E[\1_{\IA_{n}} E_{n+1}] \le \delta_{n+1} \E[\1_{\IA_{n}} E_n].
	$
	For $n\in \N$, we use Lemma~\ref{lem:Epositive} and the monotonicity of $(\IA_n)_{n \in \N_0}$ in order to show that $\E[\1_{\IA_{n}} E_n]\le \E[\1_{\IA_{n-1}} E_n]$ so that, iteratively, 
	\begin{align} \label{eq:2776362562}
		\E[\1_{\IA_{n-1}} E_{n}] \le \Bigl( \prod_{i=1}^{n}\delta_{i} \Bigr)\E[\1_{\IA_{0}} E_0].
	\end{align}
	Next, we bound the expectation of $(f(X_n))_{n \in \N_0}$ using \eqref{eq:2776362562}. Analogously to \eqref{eq:273856230}, we have for all $n \in \N_0$ that
	\begin{align*}
		\E[\1_{\IA_{n}}f(X_{n+1})]\le \E\Big[\1_{\IA_{n}} \bigl( f(X_{n})+\gamma_{n+1}\langle \grad f(X_{n+1}),V_{n+1}\rangle + \frac{C_L}{2} \gamma_{n+1}^2 \bigl|V_{n+1}\bigr|^2\bigr) \Big]
	\end{align*}
	so that, by definition of $E_{n+1}$,
	\begin{align*} 
		&(1+a\gamma_{n+1})\E[\1_{\IA_{n}}f(X_{n+1})]\\
		&\le \E\Big[ \1_{\IA_{n}} \bigl(f(X_{n})+\gamma_{n+1} E_{n+1} + (\frac{C_L}{2} \gamma_{n+1}^2- \frac{b}{2}\gamma_{n+1}) \bigl|V_{n+1}\bigr|^2 \bigr)\Big].
	\end{align*}
	By assumption, $(\frac{C_L}{2} \gamma_{n}^2- \frac{b}{2}\gamma_{n})_{n \in \N}$ is a sequence of non-positive reals. Therefore, we can neglect the last term in the upper bound above and get
	\begin{align} \label{eq:21378861}
		\E[\1_{\IA_{n}}f(X_{n+1})] \le (1+a\gamma_{n+1})^{-1} \E[\1_{\IA_n} f(X_{n})]+\frac{\gamma_{n+1}}{1+a\gamma_{n+1}} \Bigl( \prod_{i=1}^{n+1}\delta_{i} \Bigr)\E[\1_{\IA_0}E_0].
	\end{align}
	Using the non-negativity of $f(X_n)$, the monotonicity of $(\IA_n)_{n \in \N_0}$ and \eqref{eq:21378861}, one can inductively show that, for all $n \in \N$,
	\begin{align*}
		&\E[\1_{\IA_{n-1}} f(X_{n})] \\
		&\le \Bigl(\prod_{i=1}^{n} (1+a\gamma_{i})^{-1}\Bigr) \Bigl( \E[\1_{\IA_0} f(X_0)] + \sum_{i=1}^{n}  \frac{\gamma_{i}}{1+a\gamma_{i}} \Bigl(\prod_{j=1}^{i} (1+a\gamma_{j})\Bigr) \Bigl(\prod_{j=1}^{i}\delta_{j} \Bigr)\E[\1_{\IA_0}E_0] \Bigr).
	\end{align*}
\end{proof}

\begin{proposition} \label{prop:convrate}
	Let $L, a,b,\mu > 0$ and $\sigma \ge 0$. Let $(\IA_n)_{n \in \N_0}$ be a decreasing sequence of events such that, for all $n \in \N_0$, $\IA_n \in \cF_n$ and on $\IA_n$ it holds that
	\begin{align*} 
		|\grad f(X_n)|^2 \ge 2L f(X_n)  \quad \text{and} \quad \E[|D_{n+1}|^2 | \cF_n] \le \sigma f(X_n).
	\end{align*} 
	Assume that
	\begin{align} \label{eq:238877}
		\mu-a+b>0 \quad , \quad a\mu-a^2+ab-2L <0 \quad \text{and} \quad C_L -\frac{b}{2}(\mu+a-b)<0.
	\end{align}
	If $\P(\bigcap_{n \in \N_0} \IA_n)< \P(\IA_0)$ we additionally assume that $ab \ge C_L$.
	Then, for every $0<\eps<m:= \min (a, \mu-a+b)$ there exist constants $C, \bar \gamma \ge 0$ such that if $\sup_{n \in \N}\gamma_n \le \bar \gamma$ it holds that 
	\begin{enumerate}
		\item[(i)] 
		$$
		\max (\E[\1_{\IA_{n-1}} f(X_n)], 	\E[\1_{\IA_{n-1}}|V_n|^2] ) \le C \exp(- (m-\eps) t_n)
		$$
		for all $n \in \N$, where $t_n = \sum_{i=1}^n \gamma_i$.
		\item[(ii)] Let $m'<m-\eps$ and assume that $ \sum_{i=0}^\infty \exp((m'-(m-\eps)) t_i)<\infty$. Then $\exp(m' t_n) f(X_n) \to 0$ almost surely on the event $\IA_\infty= \bigcap_{n \in \N_0} \IA_n$.
		\item[(iii)] The process $(X_n)_{n \in \N_0}$ converges almost surely on $\IA_\infty$.
	\end{enumerate}
\end{proposition}

\begin{proof}
	(i): 
	First, note that, for all $x\in \R$, $1+x\le \exp(x)$ and $(1+x)^{-1}=e^{-x+o(x)}$. Thus, for every $\eps'>0$ there exists a $\bar \gamma'>0$ such that if $\max_{i=1, \dots, n} \gamma_i \le \bar \gamma'$ we have
	$$
	\prod_{i=1}^{n} (1+a\gamma_{i})^{-1} \le \Bigl(\prod_{i=1}^{n} \exp((-a+\eps')\gamma_i)\Bigr) = \exp((-a+\eps')t_n ).
	$$
	Moreover, for $(\delta_n)_{n \in \N}$ given in \eqref{eq:alpha} we have $\delta_n = 1-\gamma_n(\mu-a+b)+o(\gamma_n)$ so that, for all $\eps''>0$, there exists a $\bar \gamma ''>0$ such that if $\max_{i=1, \dots, n} \gamma_i \le \bar \gamma''$ we have $\delta_i\ge 0$ for all $i=1, \dots, n$ and
	$$
	\prod_{i=1}^{n}\delta_{i} \le \exp(-(\mu-a+b-\eps'')t_n).
	$$
	Note that $\beta_n = -\gamma_n + o(\gamma_n)$, $\alpha_n-a\delta_n+2\beta_n L =  \gamma_n (a\mu-a^2+ab-2 L)+o(\gamma_n)$, 
	$$
	\epsilon_n-\frac b2 \delta_n =  \gamma_n \Bigl(C_L-\frac{b}{2}(\mu+a-b)\Bigr) +o(\gamma_n) \;  \text{ and } \; \sfrac {C_L}{2}\gamma^2-\sfrac{b}{2}\gamma=-\sfrac{b}{2}\gamma+o(\gamma),
	$$
	and using assumption \eqref{eq:238877} we can choose $\bar \gamma \le \min(\bar \gamma',\bar \gamma'')$ sufficiently small such that if $\sup_{n \in \N}\gamma_n \le \bar \gamma$ all of the above terms are strictly negative. Then, using Proposition~\ref{prop:SHB} we get that for all $n \in \N$
	\begin{align*}
		\E[\1_{\IA_{n-1}} f(X_{n})] 
		\le \exp((&-a+\eps'+\eps'')t_n )  \\
		& \Bigl( \E[ \1_{\IA_0}f(X_0)]+ \sum_{i=1}^{n}  \gamma_{i}  \exp(-(\mu-2a+b)t_i) \E[\1_{\IA_0}E_0] \Bigr).
	\end{align*}
	If $a< \mu-a+b$, the function $t \mapsto \exp(-(\mu-2a+b)t)$ is monotonously decreasing and we get
	\begin{align*}
		\sum_{i=1}^{n}  \gamma_{i}  \exp(-(\mu-2a+b)t_i) &\le \int_{0}^{t_n} \exp(-(\mu-2a+b)t) \, dt.
	\end{align*}
	Thus,
	$$
	\E[\1_{\IA_{n-1}} f(X_{n})] \le\exp((-a+\eps'+\eps'')t_n ) \Bigl( \E[\1_{\IA_0} f(X_0)] + \frac{\E[\1_{\IA_0}E_0]}{\mu-2a+b}  \Bigr).
	$$
	For $a>\mu-a+b$,  the function $t \mapsto \exp(-(\mu-2a+b)t)$ is monotonously increasing and we get
	\begin{align*}
		\sum_{i=1}^{n}  &\gamma_{i}  \exp(-(\mu-2a+b)t_i) \le \int_{0}^{t_n} \exp(-(\mu-2a+b)(t+\bar \gamma)) \, dt.
	\end{align*}
	Thus,
	\begin{align*}
		\E[\1_{\IA_{n-1}} f(X_{n})] \le&\exp((-(\mu-a+b)+\eps'+\eps'')t_n ) \Bigl( \E[\1_{\IA_0} f(X_0)] \\
		& \qquad \qquad \qquad  +\frac{\E[\1_{\IA_0}E_0]}{2a-\mu-b} \bigl(\exp(-(\mu-2a+b)\bar \gamma)  \Bigr).
	\end{align*}
	Lastly, for $a=\mu-a+b$ we get 
	$
	\sum_{i=1}^{n}  \gamma_{i}  \exp(-(\mu-2a+b)t_i)=t_n
	$
	and, thus,
	$$
	\E[\1_{\IA_{n-1}}f(X_n)] \le \exp((-a+\eps'+\eps'')t_n ) \Bigl( \E[ \1_{\IA_0}f(X_0)] + t_n\E[\1_{\IA_0}E_0] \Bigr).
	$$
	Note that $\exp(-\eps''' t)t \to 0$ for all $\eps'''>0$. Therefore, there exists a constant $C'>0$ such that
	$$
	\E[\1_{\IA_{n-1}}f(X_{n})] \le \exp((-a+\eps'+\eps''+\eps''')t_n ) \Bigl( \E[\1_{\IA_0} f(X_0)] + C'\E[\1_{\IA_0}E_0] \Bigr).
	$$
	The proof of the first assertion follows by choosing $\eps'=\eps''= \eps''' =\frac 13 \eps$.
	
	For the second assertion, note that, by Lemma~\ref{rem:Lipschitz}, we have $|\grad f(x)|^2 \le 2 C_L f(x)$ for all $x \in \R^d$
	and, using that $f(X_n)\ge 0$, we get by the Cauchy-Schwarz inequality
	\begin{align*}
		\frac b2 |V_n|^2 &\le E_n - \langle \grad f(X_n), V_n \rangle \le E_n + |\grad f(X_n)| \, |V_n|,
	\end{align*}
	where $E_n$ is defined by \eqref{eq:Lyapunov}.
	Thus, using Young's inequality, 
	\begin{align} \label{eq:Yconv2}
		\frac b2 \E\bigl[\1_{\IA_{n-1}}  |V_n|^2\bigr]
		&\le \E[\1_{\IA_{n-1}} E_n] + \frac 1b \E[\1_{\IA_{n-1}} |\grad f(X_n)|^2] + \frac b4\E[ \1_{\IA_{n-1}} |V_n|^2] 
	\end{align}
	and, with the bound for $\E[\1_{\IA_{n-1}} f(X_n)]$ and \eqref{eq:2776362562}, we get a constant $C\ge 0$ such that 
	\begin{align} \label{eq:Yconv} 
		\E[\1_{\IA_{n-1}}|V_n|^2]^{1/2} \le C \exp\Bigl(-\frac 12 (m -\eps)t_n\Bigr).
	\end{align}
	
	(ii): Let $m'<m-\eps$. For $\eps' >0$ and $n \in \N$ consider the set $\IB_n = \IA_\infty \cap \{\sup_{i \ge n} \exp(m' t_i) f(X_i) \ge \eps' \}$.
	With the Markov inequality and (i) there exists a $C>0$ such that
	\begin{align*}
		\P(\IB_n) &\le \sum_{i=n}^\infty \P\bigl(\IA_{i-1} \cap \bigl\{\exp(m' t_i) f(X_i) \ge \frac{\eps'}{2}\bigr\}\bigr) \\
		& \le \sum_{i=n}^\infty \frac{2\exp(m' t_i)}{\eps'} \E[\1_{\IA_{i-1}} f(X_i)] \le \frac{C}{\eps'} \sum_{i=n}^\infty \exp((m'-(m-\eps)) t_i) \overset{n \to \infty}{\longrightarrow} 0.
	\end{align*}
	With
	$$
	\P\Bigl(\IA_\infty \cap \big\{\limsup_{n \to \infty} \exp(m' t_n)f(X_n) \ge \eps'\big\}\Bigr) \le \P\Bigl(\bigcap_{n \in \N} B_n\Bigr) =0
	$$
	we get $\exp(m' t_n)f(X_n)\to 0$ almost surely on $\IA_\infty$.
	
	(iii):
	We consider the event $\IA_\infty$ and bound the distance that the process $(X_n)_{n \in \N_0}$ travels. Since $\eps < m$ the mapping $t  \mapsto \exp(-\frac 12 (m -\eps)t)$ is monotonously decreasing. Thus, using \eqref{eq:Yconv} we get
	\begin{align*}
		\E\Bigl[\1_{\IA_\infty} \sum_{i=1}^\infty |X_i-X_{i-1}|\Bigr] &\le   \sum_{i=1}^\infty \gamma_i \E[\1_{\IA_{i-1}}  |V_i|^2]^{1/2} \le C \sum_{i=1}^\infty \gamma_i  \exp\Bigl(-\frac 12 (m -\eps)t_i\Bigr)\\
		&\le C \int_0^\infty \exp\Bigl(-\frac 12 (m -\eps)t\Bigr) \, dt < \infty,
	\end{align*}
	which implies that $\sum_{i=1}^\infty |X_i-X_{i-1}|$ is almost surely finite, on $\IA_\infty$. Thus, $(X_n)_{n \in \N_0}$ almost surely converges on $\IA_{\infty}$.
\end{proof}

\begin{lemma} \label{lem:feasible1}
	For all $\mu >0$ there exist $a,b >0$ such that $ab \ge C_L$ and \eqref{eq:238877} is satisfied.
\end{lemma}

\begin{proof}
	Let $\eps,b>0$ and choose $a=b+2\frac{C_L}{b}-\mu+\eps$. Note that $a>0$ iff $\mu < b+2\frac {C_L}{b}+\eps$. Moreover, $\mu-a+b=2(\mu-\frac{C_L}{b})-\eps$ is positive iff $\mu > \frac{C_L}{b}+\frac{\eps}{2}$. Now, 
	$
	C_L-\frac b2(\mu+a-b)=-\frac{b}{2}\eps < 0
	$
	and we have 
	$$
	a\mu-a^2+ab-2L = -2\mu^2+2\mu\Bigl(b+\frac{3C_L}{b}+\frac{3\eps}{2}\Bigr)-2C_L-2L-4\frac{C_L^2}{b^2}-2\eps\Bigr(\frac b2 + 2\frac{C_L}{b}+\frac{\eps}{2}\Bigl).
	$$
	The latter term is a quadratic function in $\mu$ that is negative outside of the two roots. Therefore, $a\mu-a^2+ab-2L <0$ iff $\mu \notin [\mu_-^{\eps,b},\mu_+^{\eps,b}]$, where
	\begin{align} \label{eq:mu}
		\mu_{\pm}^{\eps,b} = \frac 12 \Bigl( b+\frac{3C_L}{b}+\frac{3\eps}{2} \pm \sqrt{\Bigl(b+\frac{C_L}{b}+\frac{\eps}{2}\Bigr)^2-4L} \,  \Bigr).
	\end{align}
	Note that $(b+\frac{C_L}{b})^2\ge 4C_L$, for all $b >0$, and $C_L\ge L$ so that $\mu_{\pm}^{\eps,b}$ is well-defined.
	Moreover, $\mu_-^{\eps,b}>\frac{C_L}{b}+\frac{\eps}{2}$ and $\mu_+^{\eps,b}<b+2\frac{C_L}{b}+\eps$. The additional assumption $ab\ge C_L$ is satisfied iff $\mu\le b+ \frac{C_L}{b}+\eps$. Therefore, the set of friction parameters $\mu$ that satisfy \eqref{eq:238877} for the given pair $(a,b)$ is equal to
	$
	(\frac{C_L}{b}+\frac{\eps}{2},\mu_-^{\eps,b}) \cup (\mu_+^{\eps,b}, b+2\frac{C_L}{b}+\eps)
	$
	and the set of friction parameters $\mu$ that satisfy both \eqref{eq:238877} and $ab \ge C_L$ for the given pair $(a,b)$ contains the interval
	$
	(\sfrac{C_L}{b}+\sfrac{\eps}{2}, \mu_-^{\eps,b} \wedge (b+\sfrac{C_L}{b}+\eps)).
	$
	For all $b>0$, the latter interval is non-empty, the upper and lower limits are continuous in $b$ and the lower limit satisfies 
	$$
	\frac{C_L}{b}+\frac{\eps}{2} \overset{b \to \infty}{\longrightarrow} \frac{\eps}{2} \quad \text{ and } \quad \frac{C_L}{b}+\frac{\eps}{2} \overset{b \to 0}{\longrightarrow} \infty.
	$$
	By letting $\eps \to 0$ we showed that for every $\mu>0$ there exists a pair $(a,b)$ such that \eqref{eq:238877} is satisfied and $ab \ge C_L$.
\end{proof}

\begin{lemma} \label{lem:49378}
	Let $L, b, \eps > 0$ and $\sigma \ge 0$. Let $(\IA_n)_{n \in \N_0}$ be a decreasing sequence of events such that, for all $n \in \N_0$, $\IA_n \in \cF_n$ and on $\IA_n$ it holds that
	\begin{align*} 
		|\grad f(X_n)|^2 \ge 2L f(X_n) \quad \text{and} \quad \E[|D_{n+1}|^2 | \cF_n] \le \sigma f(X_n).
	\end{align*} 
	Let 
	$
	\mu \in (\frac{C_L}{b}+\frac{\eps}{2}, \mu_-^{\eps,b}) \cup (\mu_+^{\eps,b}, b+2\frac{C_L}{b}+\eps),
	$
	where $\mu_{\pm}^{\eps,b}$ is defined by \eqref{eq:mu}.
	If $\P(\bigcap_{n \in \N_0}\IA_n)<\P(\IA_0)$ additionally assume that $\mu \le b+\frac{C_L}{b}+\eps$. Then, there exist $C, \bar \gamma>0$ such that if $\sup_{n \in \N}\gamma_n \le \bar \gamma$ we have
	$$
	\E[\1_{\IA_{n-1}} f(X_n)] \le C \exp(-m(\eps,b,\mu) t_n),
	$$
	where
	\begin{align*} 
		m(\eps,b,\mu) = \begin{cases} 
			2(\mu-\frac{C_L}{b}-\eps), & \text{ if } \mu < \frac{1}{3} (b+4\frac{C_L}{b}+2\eps) \\
			b+2\frac{C_L}{b}-\mu, & \text{ if } \mu \ge \frac{1}{3} (b+4\frac{C_L}{b}+2\eps).
		\end{cases}
	\end{align*}
\end{lemma}

\begin{proof}
	Let $\eps, b>0$ and $\mu$ as in the assumptions of the lemma and set $a=b+2\frac{C_L}{b}-\mu+\eps$. Recall that in the proof of Lemma~\ref{lem:feasible1} we showed that this choice of parameters satisfies \eqref{eq:238877} and if $\P(\bigcap_{n \in \N_0}\IA_n)<\P(\IA_0)$, additionally, $ab \ge C_L$. Hence, we can apply Proposition~\ref{prop:convrate} and deduce that there exist constants $C, \bar \gamma >0$ such that, if $\sup_{n \in \N}\gamma_n \le \bar \gamma$, we have
	$$
	\E[\1_{\IA_{n-1}}f(X_n)] \le C \exp(-m(\eps,b,r) t_n),
	$$
	where
	$$
	m(\eps,b,\mu)= \min(a,\mu-a+b)-\eps= \min\Bigl(b+2\frac{C_L}{b}-\mu,2\Bigl(\mu-\frac{C_L}{b}-\eps\Bigr)\Bigr).
	$$
	The evaluation of the minimum is straight-forward.
\end{proof}

\begin{proof} [Proof of Theorem~\ref{theo2}]
	We maximize the convergence rate derived in Lemma~\ref{lem:49378} over all admissible parameters $\mu$ and $b$.
	First, assume that $\kappa=\frac{C_L}{L}<\frac 98$. Then, we have for all sufficiently small $\eps>0$ that $\kappa^\eps := \bigl(\frac{\sqrt {C_L}}{\sqrt{L}}+\frac{\eps}{4\sqrt{L}}\bigr)^2<\frac{9}{8}$ so that Set \begin{align*}
		b_{\pm}^\eps := \frac{3}{\sqrt 8} \sqrt L -\frac{\eps}{4} \pm \sqrt{\Bigl( \frac{3}{\sqrt 8} \sqrt L -\frac{\eps}{4} \Bigr)^2-C_L}
	\end{align*}
	is well-defined.
	For $b \in (b_-^\eps, b_+^\eps)$ we have $\frac{1}{3} (b+4\frac{C_L}{b}+2\eps)<\mu_-^{\eps, b}$, such that with Lemma~\ref{lem:49378} we get for $\mu \in (\frac{C_L}{b}+\frac{\eps}{2},\frac 13(b+4\frac{C_L}{b}+2\eps))$ the convergence rate $m(\eps, b ,\mu)=2\bigl( \mu-\frac{C_L}{b} -\eps\bigr)$. Note that
	$$
	\frac{d}{d\eps}\big|_{\eps=0} \frac 13 \Bigl(b_+^\eps-\eps^2+4\frac{C_L}{b_+^\eps-\eps^2}+2\eps\Bigr) =\frac 14 + \frac{3 \sqrt L}{4 \sqrt{9L-8C_L}}>0.
	$$ 
	Therefore, for sufficiently small $\eps$, we have 
	$$
	\mu^*_1 := \frac{1}{3} \Bigl(b_+^0+4\frac{C_L}{b_+^0}\Bigr) = \frac{1}{\sqrt 8}(5-\sqrt{ 9 - 8\kappa})\sqrt{L}<\frac 13 \Bigl(b_+^\eps-\eps^2+4\frac{C_L}{b_+^\eps-\eps^2}+2\eps\Bigr)
	$$
	and we
	get by continuity that
	\begin{align*}
		m(\eps, b_+^\eps-\eps^2,\mu^*_1) &\overset{\eps \to 0}{\longrightarrow} \frac 23 \Bigl(b_+^0+\frac{C_L}{b_+^0}\Bigr) = \frac 23 \frac{(b_+^0)^2+C_L}{b_+^0} = \sqrt {2L}.
	\end{align*}
	Moreover, note that $b_+^0$ satisfies $\frac 13 (b_+^0+4\frac{C_L}{b_+^0})<b_+^0+\frac{C_L}{b_+^0}$ since 
	$$
	\frac{C_L}{b_+^0} = \frac {1}{\sqrt 8} (3 \sqrt L -\sqrt{9L-8C_L})<\frac{1}{\sqrt 2}(3\sqrt L +\sqrt{9L-8 C_L})=2b_+^0.
	$$
	Thus, $b_+^0 (b_+^0+2\frac{C_L}{b_+^0}-\mu^*_1) > C_L$ and, for sufficiently small $\eps>0$, the parameters $b= b_+^\eps-\eps^2$ and $a=b_+^\eps-\eps^2+2\frac{C_L}{b_+^\eps-\eps^2}-\mu^*_1+\eps$ satisfy $ab\ge C_L$.
	
	Analogously, we get the convergence rate $m(\eps,b,\mu)=b+2\frac{C_L}{b}-\mu$ if $b \in (b_-^\eps,b_+^\eps)$ and $\mu \in (\frac 13(b+4\frac{C_L}{b}+2\eps),\mu_-^{\eps,b})$. Note that, since $\kappa < \frac 98$ we have
	$$
	\frac{d}{d\eps}\big|_{\eps=0} \frac 13 \Bigl(b_-^\eps+\eps^2+4\frac{C_L}{b_-^\eps+\eps^2}+2\eps\Bigr) = \frac 14 - \frac{3 \sqrt{L}}{4\sqrt{9L-8C_L}}<0.
	$$
	Therefore, for sufficiently small $\eps$, we have
	$$
	\mu^*_2 := \frac{1}{3} \Bigl(b_-^0+4\frac{C_L}{b_-^0}\Bigr) = \frac{1}{\sqrt 8}\bigl(5+\sqrt{ 9 - 8\kappa}\bigr)\sqrt{L} > \frac 13\Bigl(b_-^\eps+\eps^2+4\frac{C_L}{b_-^\eps+\eps^2}+2\eps\Bigr)
	$$
	and we get by continuity that
	\begin{align*}
		m(\eps, b_-^\eps+\eps^2,\mu^*_2) &\overset{\eps \to 0}{\longrightarrow} b_-^0+2\frac{C_L}{b_-^0}-\mu^* = \frac 23 \frac{(b_-^0)^2+C_L}{b_-^0}  = \sqrt {2L}.
	\end{align*}
	If $L<C_L$, $b_-^0$ satisfies $\frac 13 (b_-^0+4\frac{C_L}{b_-^0})<b_-^0+\frac{C_L}{b_-^0}$ since 
	$$
	\frac{C_L}{b_-^0} = \frac {1}{\sqrt 8} (3 \sqrt L +\sqrt{9L-8C_L})<\frac{1}{\sqrt 2}(3\sqrt L -\sqrt{9L-8 C_L})=2b_-^0.
	$$
	Thus, for sufficiently small $\eps>0$, $b=b_-^\eps+\eps^2$ and $a=b_-^\eps+\eps^2+2\frac{C_L}{b_-^\eps+\eps^2}-\mu^*_2+\eps$ satisfy $ab\ge C_L$.
	If $L=C_L$, we have $\mu^*_2=b_-^0+\frac{C_L}{b_-^0}$. Using
	$
	\frac{d}{d\eps}\big|_{\eps=0} \Bigl( b_-^\eps+\frac{C_L}{b_-^\eps}+\eps\Bigr) = \frac 12,
	$
	we get $\mu^*_2 \le b_-^\eps +\eps^2 + \frac{C_L}{b_-^\eps+\eps^2}+\eps$ for sufficiently small $\eps>0$ and, thus, $ab\ge C_L$ for the parameters $b=b_-^\eps+\eps^2$ and $a=b_-^\eps+\eps^2+2\frac{C_L}{b_-^\eps+\eps^2}-\mu^*_2+\eps$.
	Lastly, note that without loss of generality we can increase the Lipschitz constant $C_L$ as long as $\kappa<\frac 98$. We thus get that all friction parameters
	$$
	\mu \in \Bigl[\frac{1}{\sqrt 8}\bigl(5-\sqrt{ 9 - 8\kappa}\bigr)\sqrt{L}, \frac{1}{\sqrt 8}\bigl(5+\sqrt{ 9 - 8\kappa}\bigr)\sqrt{L}  \Bigr] \Big\backslash\Bigl\{\frac{5}{\sqrt 8}\sqrt{L}\Bigr\}
	$$
	give an optimal convergence rate of $\sqrt{2L}-\eps$. The case $\mu=\frac{5}{\sqrt 8}\sqrt{L}$ corresponds to $\kappa=\frac 98$ and will be treated below.
	
	Next, assume that $\kappa \ge \frac 98$ which implies that, for all $\eps > 0$, we have $\kappa^\eps \ge \frac{9}{8}$. 
	Using Lemma~\ref{lem:49378}, we get the convergence rate $m(\eps,b,\mu)=2(\mu-\frac{C_L}{b}-\eps)$ if $\mu \in (\frac{C_L}{b}+\frac{\eps}{2}, \mu_-^{\eps,b})$.	
	First, note that if $\mu_-^{0,b} \in (\frac{C_L}{b}+\frac{\eps}{2}, \mu_-^{\eps,b})$ we have
	$$
	m(\eps, b, \mu_-^{0,b})=  b+\frac{C_L}{b} - \sqrt{\Bigl(b+\frac{C_L}{b}\Bigr)^2-4L}-2\eps.
	$$
	Moreover, $m(\eps, b,\mu_-^{0,b}) \overset{b \to 0}{\longrightarrow}-2\eps$ and $m(\eps, b,\mu_-^0) \overset{b \to \infty}{\longrightarrow}-2\eps$ as well as
	$$
	\frac{d}{db} m(\eps,b,\mu_-^{0,b}) = \Bigl( 1-\frac{C_L}{b^2} \Bigr) \Bigl( 1-\frac{b+C_L/b}{\sqrt{(b+C_L/b)^2-4L}} \Bigr),
	$$
	so that	
	$\frac{d}{db}m(\eps,b,\mu_-^{0,b})>0$ for all $b< \sqrt{C_L}$ and $\frac{d}{db}m(\eps,b,\mu_-^{0,b})<0$ for all $b> \sqrt{C_L}$. Therefore, the maximal value for $m(\eps,b,\mu_-^{0,b})$ is attained at $b^*=\sqrt{C_L}$, where 
	$$
	\mu^*_3= \mu_-^{0,b^*} = 2\sqrt{C_L}-\sqrt{C_L-L} = (2\sqrt \kappa-\sqrt{\kappa-1})\sqrt L
	$$
	and 
	$$
	m(\eps, b^*,\mu^*_3)=2(\sqrt{C_L}-\sqrt{C_L-L}-\eps) \overset{\eps \to 0}{\longrightarrow} 2(\sqrt{\kappa}-\sqrt{\kappa-1})\sqrt L.
	$$
	Now, consider 
	\begin{align*}
		\mu_{-}^{\eps,b^*} &= \frac 12 \Bigl( 4 \sqrt{C_L}+\frac{3\eps}{2} - \sqrt{\bigl(2 \sqrt{C_L}+\frac{\eps}{2}\bigr)^2-4L} \,  \Bigr)
	\end{align*}
	as a function of $\eps$. Note that for all $\eps\ge 0$ we have $
	\frac{L}{C_L} \le \frac 29 \Bigl( 2+\frac{\eps}{2\sqrt{C_L}} \Bigr)^2,
	$ and, thus,
	\begin{align*}
		\frac{d}{d\eps} \mu_{-}^{\eps,b^*} &= \frac 12 \Bigl( \frac 32 - \frac 12 \Bigl(\bigl(2 \sqrt{C_L}+\frac{\eps}{2}\bigr)^2-4L\Bigr)^{-1/2}  \bigl(2 \sqrt{C_L}+\frac{\eps}{2}\bigr) \Bigr) \ge 0
	\end{align*}
	Therefore, for sufficiently small $\eps >0$ we have $\mu^*_3 \in (\frac{C_L}{b^*}+\frac{\eps}{2}, \mu_-^{\eps,b^*})$.
	Moreover, note that
	$
	\mu^* _3 < 2 \sqrt{C_L} = b^* + \frac{C_L}{b^*}
	$
	such that the parameters $b^*$ and $a=b^*+2\frac{C_L}{b^*}-\mu+\eps$ satisfy $ab^*\ge C_L$. Finally, for $\kappa = \frac 98$ we get $2(\sqrt{\kappa}-\sqrt{\kappa-1})\sqrt L= \sqrt{2L}$ and $\mu^*_3=\frac{5}{\sqrt 8}\sqrt L$.
\end{proof}

