\begin{lemma} \label{rem:Lipschitz}
	Let $r>0$, $y \in \R^d$ and assume that $\grad f$ is $C_L$-Lipschitz continuous on $B_r(y)$ and $\inf_{x \in B_r(y)}f(x)=f(y)$. Then, for all $x \in B_{r/2}(y)$ it holds that
	\begin{align} \label{eq:inversePL}
		|\grad f(x)|^2 \le 2 C_L (f(x)-f(y)).
	\end{align}
\end{lemma}

\begin{lemma} \label{lem:Epositive}
	Let $a, b, C_L>0$ and
	\begin{align*}
		E(x,y) = a f(x) + \langle \grad f(x), y \rangle + \frac{b}{2} |y|^2.
	\end{align*}
	If $ab\ge C_L$ then for all $x \in \R^d$ satisfying $2C_L f(x)\ge |\grad f(x)|^2$ we have $E(x,y)\ge 0$, for all $y \in \R^d$.
\end{lemma}

\begin{proof}
	If $\grad f(x)=0$ the statement is trivial. If $\grad f(x) \neq 0$, we denote $\rho=\frac{|y|}{|\grad f(x)|}$ and get
	$$
	E(x,y) \ge \Bigl(\frac{a}{2C_L}-\rho+\frac{b}{2}\rho^2 \Bigr) |\grad f(x)|^2.
	$$
	The quadratic function $\varphi(\rho)=\frac{a}{2C_L}-\rho+\frac{b}{2}\rho^2$ attains its global minimum at $\rho=\frac{1}{b}$ and using $ab \ge C_L$ we deduce that
	\begin{align*}
		\varphi\Bigl(\frac 1b\Bigr)=\frac{a}{2C_L}-\frac{1}{2b}\ge 0.
	\end{align*}
\end{proof}

\begin{proposition} \label{prop:SHB}
	Let $L,a,b>0, \sigma \ge 0$. Let $(\IA_n)_{n \in \N_0}$ be a decreasing sequence of events such that, for all $n \in \N_0$, $\IA_n \in \cF_n$ and on $\IA_n$ it holds that
	\begin{align} \label{eq:1293182}
		|\grad f(X_n)|^2 \ge 2L f(X_n) \quad \text{and} \quad \E[|D_{n+1}|^2 | \cF_n] \le \sigma f(X_n).
	\end{align}
	Let $(\alpha_n)_{n \in \N}, (\beta_n)_{n \in \N}, (\delta_n)_{n \in \N}$ and $(\epsilon_n)_{n \in \N}$ be given by $\eqref{eq:alpha}$. Assume that $(\beta_n)_{n \in \N}$, $(\alpha_{n+1}-a\delta_{n+1}+2\beta_{n+1}L)_{n \in \N_0}$, $(\epsilon_{n+1}-\frac{b}{2} \delta_{n+1})_{n \in \N_0}$ and $(\frac{C_L}{2} \gamma_{n}^2- \frac{b}{2}\gamma_{n})_{n \in \N_0}$ are sequences of non-positive reals and $(\delta_n)_{n \in \N}$ is a sequence of non-negative reals.
	Moreover, if $\P(\bigcap_{n \in \N_0} \IA_n)<\P(\IA_0)$ additionally assume that $ab \ge C_L$.
	Then, for all $n \in \N$ it holds that
	\begin{align}\begin{split} \label{eq:238477}
			& \E[\1_{\IA_{n-1}} f(X_{n})]\le \Bigl(\prod_{i=1}^{n} (1+a\gamma_{i})^{-1}\Bigr) \\
			& \qquad \qquad \qquad \Bigl( \E[\1_{\IA_0} f(X_0)] + \sum_{i=1}^{n}  \frac{\gamma_{i}}{1+a\gamma_{i}} \Bigl(\prod_{j=1}^{i} (1+a\gamma_{j})\Bigr) \Bigl(\prod_{j=1}^{i}\delta_{j} \Bigr)\E[\1_{\IA_0}E_0] \Bigr).
		\end{split} 
	\end{align}	
\end{proposition}

\begin{proof}
	In a first step, we derive a convergence rate for the expectation of the Lyapunov process $(E_n)_{n \in \N_0}$. For this, we consider the time evolution of the three summands in \eqref{eq:Lyapunov}, separately.
	
	First, we look at the evolution of $(f(X_{n}))_{n \in \N_0}$.
	Let $x,y \in \R^d$ and note that with the Lipschitz-continuity of $\grad f$ we get
	\begin{align}
		\begin{split}
			\label{eq:Taylorp1}
			f(y)&\le f(x) + \langle \grad f(x),y-x\rangle  + \frac{C_L}{2} |y-x|^2.
		\end{split}
	\end{align}
	
	Now, for $n \in \N_0$ we use \eqref{eq:Taylorp1} with $x=X_{n}$ and $y=X_{n+1}$ and \eqref{eq:MSGDintro} to get 
	\begin{align} \begin{split} 
			\label{eq:273856230}
			&\E[\1_{\IA_n}f(X_{n+1})]\le \E\Big[\1_{\IA_n}\bigl(f(X_{n})-\gamma_{n+1}^2 |\grad f(X_n)|^2 \\
			&\qquad \qquad \qquad \qquad \quad + (\gamma_{n+1}-\gamma_{n+1}^2\mu) \langle \grad f(X_{n}),V_n\rangle + \frac{C_L}{2} \gamma_{n+1}^2 \bigl|V_{n+1}\bigr|^2 \bigr) \Big].
		\end{split}
	\end{align}
	
	Next, we control the evolution of $(|V_n|^2)_{n \in \N_0}$. Using \eqref{eq:1293182}, we get
	\begin{align} \begin{split}
			\E[\1_{\IA_n}|V_{n+1}|^2]
			\le  \E[\1_{\IA_n}(&(1-2\gamma_{n+1}\mu+\gamma_{n+1}^2\mu^2)|V_n|^2+ \gamma_{n+1}^2 |\grad f(X_n)|^2  \\
			&  - 2 (\gamma_{n+1}-\gamma_{n+1}^2\mu) \langle V_n, \grad f(X_n)\rangle  + \gamma_{n+1}^2 \sigma f(X_n))].
		\end{split}
	\end{align}
	Lastly,
	\begin{align} \begin{split} \label{eq:1764443}
			\E[\1_{\IA_n} &\langle \grad f(X_{n+1}), V_{n+1} \rangle] = \E[ \1_{\IA_n} (\langle \grad f(X_{n}), V_{n+1} \rangle + \langle \grad f(X_{n+1})- \grad f(X_{n}), V_{n+1} \rangle )] \\
			&\le \E[\1_{\IA_n} ((1-\gamma_{n+1}\mu) \langle \grad f(X_n), V_n \rangle - \gamma_{n+1}  |\grad f(X_n)|^2 + C_L \gamma_{n+1} |V_{n+1}|^2)].
		\end{split}
	\end{align}
	
	Combining the estimates \eqref{eq:273856230}-\eqref{eq:1764443}, we obtain
	\begin{align*}
		&\E[\1_{\IA_{n}} E_{n+1}] \\
		&\le \E[\1_{\IA_{n}}(\alpha_{n+1} f(X_n) + \beta_{n+1} |\grad f(X_n)|^2 +\delta_{n+1} \langle \grad f(X_n),V_n \rangle + \epsilon_{n+1} |V_n|^2)],
	\end{align*}
	where
	\begin{align} \label{eq:alpha}
		\begin{split}
			\alpha_{n+1} = &a + \Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr)\gamma_{n+1}^2 \sigma, \\
			\beta_{n+1} = &- \gamma_{n+1} - a\gamma_{n+1}^2 + \Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr)\gamma_{n+1}^2,\\
