			&- 2\Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr) (\gamma_{n+1}-\gamma_{n+1}^2\mu), \\
			\epsilon_{n+1} = &\Bigl(\frac{b}{2}+C_L \gamma_{n+1}\Bigl(1+\frac{\gamma_{n+1}a}{2}\Bigr)\Bigr) (1-2\gamma_{n+1}\mu+\gamma_{n+1}^2\mu^2).
		\end{split}
	\end{align}
	By definition
	$
	\E[\1_{\IA_n} \langle \grad f(X_n), V_n \rangle ] =  \E[\1_{\IA_n}(E_n -a f(X_n)-\sfrac{b}{2} |V_n|^2)],
	$
	so that, using the PL-inequality \eqref{eq:1293182} and the fact that $(\beta_n)_{n \in \N}$ is non-positive, we get 
	\begin{align} \begin{split} \label{eq:579999663}
			&\E[\1_{\IA_{n}}E_{n+1}] \\
			&\le \E[\1_{\IA_n}(\delta_{n+1}E_n + (\alpha_{n+1}-a\delta_{n+1}+2\beta_{n+1}L) f(X_n)  + (\epsilon_{n+1}-\frac{b}{2} \delta_{n+1}) |V_n|^2)].
		\end{split}
	\end{align}
	With the assumptions on $(\alpha_{n+1}-a\delta_{n+1}+2\beta_{n+1}L)_{n \in \N_0}$ and $(\epsilon_{n+1}-\frac{b}{2} \delta_{n+1})_{n \in \N_0}$ we have
	$
	\E[\1_{\IA_{n}} E_{n+1}] \le \delta_{n+1} \E[\1_{\IA_{n}} E_n].
	$
	For $n\in \N$, we use Lemma~\ref{lem:Epositive} and the monotonicity of $(\IA_n)_{n \in \N_0}$ in order to show that $\E[\1_{\IA_{n}} E_n]\le \E[\1_{\IA_{n-1}} E_n]$ so that, iteratively, 
	\begin{align} \label{eq:2776362562}
		\E[\1_{\IA_{n-1}} E_{n}] \le \Bigl( \prod_{i=1}^{n}\delta_{i} \Bigr)\E[\1_{\IA_{0}} E_0].
	\end{align}
	Next, we bound the expectation of $(f(X_n))_{n \in \N_0}$ using \eqref{eq:2776362562}. Analogously to \eqref{eq:273856230}, we have for all $n \in \N_0$ that
	\begin{align*}
		\E[\1_{\IA_{n}}f(X_{n+1})]\le \E\Big[\1_{\IA_{n}} \bigl( f(X_{n})+\gamma_{n+1}\langle \grad f(X_{n+1}),V_{n+1}\rangle + \frac{C_L}{2} \gamma_{n+1}^2 \bigl|V_{n+1}\bigr|^2\bigr) \Big]
	\end{align*}
	so that, by definition of $E_{n+1}$,
	\begin{align*} 
		&(1+a\gamma_{n+1})\E[\1_{\IA_{n}}f(X_{n+1})]\\
		&\le \E\Big[ \1_{\IA_{n}} \bigl(f(X_{n})+\gamma_{n+1} E_{n+1} + (\frac{C_L}{2} \gamma_{n+1}^2- \frac{b}{2}\gamma_{n+1}) \bigl|V_{n+1}\bigr|^2 \bigr)\Big].
	\end{align*}
	By assumption, $(\frac{C_L}{2} \gamma_{n}^2- \frac{b}{2}\gamma_{n})_{n \in \N}$ is a sequence of non-positive reals. Therefore, we can neglect the last term in the upper bound above and get
	\begin{align} \label{eq:21378861}
		\E[\1_{\IA_{n}}f(X_{n+1})] \le (1+a\gamma_{n+1})^{-1} \E[\1_{\IA_n} f(X_{n})]+\frac{\gamma_{n+1}}{1+a\gamma_{n+1}} \Bigl( \prod_{i=1}^{n+1}\delta_{i} \Bigr)\E[\1_{\IA_0}E_0].
	\end{align}
	Using the non-negativity of $f(X_n)$, the monotonicity of $(\IA_n)_{n \in \N_0}$ and \eqref{eq:21378861}, one can inductively show that, for all $n \in \N$,
	\begin{align*}
		&\E[\1_{\IA_{n-1}} f(X_{n})] \\
		&\le \Bigl(\prod_{i=1}^{n} (1+a\gamma_{i})^{-1}\Bigr) \Bigl( \E[\1_{\IA_0} f(X_0)] + \sum_{i=1}^{n}  \frac{\gamma_{i}}{1+a\gamma_{i}} \Bigl(\prod_{j=1}^{i} (1+a\gamma_{j})\Bigr) \Bigl(\prod_{j=1}^{i}\delta_{j} \Bigr)\E[\1_{\IA_0}E_0] \Bigr).
	\end{align*}
\end{proof}

In a first step, we derive a convergence rate for the expectation of the Lyapunov process $(E_n)_{n \in \N_0}$. For this, we consider the time evolution of the three summands in \eqref{eq:Lyapunov}, separately.

First, we look at the evolution of $(f(X_{n}))_{n \in \N_0}$.
Let $x,y \in \R^d$ and note that with the Lipschitz-continuity of $\grad f$ we get
\begin{align}
	\begin{split}
