	\end{split}
\end{align}

Now, for $n \in \N_0$ we use \eqref{eq:Taylorp1} with $x=X_{n}$ and $y=X_{n+1}$ and \eqref{eq:MSGDintro} to get 
\begin{align} \begin{split} 
