		&\E[\1_{\IA_n}f(X_{n+1})]\le \E\Big[\1_{\IA_n}\bigl(f(X_{n})-\gamma_{n+1}^2 |\grad f(X_n)|^2 \\
		&\qquad \qquad \qquad \qquad \quad + (\gamma_{n+1}-\gamma_{n+1}^2\mu) \langle \grad f(X_{n}),V_n\rangle + \frac{C_L}{2} \gamma_{n+1}^2 \bigl|V_{n+1}\bigr|^2 \bigr) \Big].
	\end{split}
\end{align}

Next, we control the evolution of $(|V_n|^2)_{n \in \N_0}$. Using \eqref{eq:1293182}, we get
\begin{align} \begin{split}
		\E[\1_{\IA_n}|V_{n+1}|^2]
		\le  \E[\1_{\IA_n}(&(1-2\gamma_{n+1}\mu+\gamma_{n+1}^2\mu^2)|V_n|^2+ \gamma_{n+1}^2 |\grad f(X_n)|^2  \\
		&  - 2 (\gamma_{n+1}-\gamma_{n+1}^2\mu) \langle V_n, \grad f(X_n)\rangle  + \gamma_{n+1}^2 \sigma f(X_n))].
	\end{split}
\end{align}

Lastly,
\begin{align} \begin{split} \label{eq:1764443}
		\E[\1_{\IA_n} &\langle \grad f(X_{n+1}), V_{n+1} \rangle] = \E[ \1_{\IA_n} (\langle \grad f(X_{n}), V_{n+1} \rangle + \langle \grad f(X_{n+1})- \grad f(X_{n}), V_{n+1} \rangle )] \\
		&\le \E[\1_{\IA_n} ((1-\gamma_{n+1}\mu) \langle \grad f(X_n), V_n \rangle - \gamma_{n+1}  |\grad f(X_n)|^2 + C_L \gamma_{n+1} |V_{n+1}|^2)].
	\end{split}
\end{align}

Combining the estimates \eqref{eq:273856230}-\eqref{eq:1764443}, we obtain
\begin{align*}
	&\E[\1_{\IA_{n}} E_{n+1}] \\
	&\le \E[\1_{\IA_{n}}(\alpha_{n+1} f(X_n) + \beta_{n+1} |\grad f(X_n)|^2 +\delta_{n+1} \langle \grad f(X_n),V_n \rangle + \epsilon_{n+1} |V_n|^2)],
\end{align*}
where
\begin{align} \label{eq:alpha}
