\begin{lemma} \label{rem:Lipschitz}
	Let $r>0$, $y \in \R^d$ and assume that $\grad f$ is $C_L$-Lipschitz continuous on $B_r(y)$ and $\inf_{x \in B_r(y)}f(x)=f(y)$. Then, for all $x \in B_{r/2}(y)$ it holds that
	\begin{align} \label{eq:inversePL}
		|\grad f(x)|^2 \le 2 C_L (f(x)-f(y)).
	\end{align}
\end{lemma}

Note that for $x \in B_{r/2}(y)$ and all $t \in [0, \frac{|\grad f(x)|}{C_L}]$ we have $x-t \frac{\grad f(x)}{|\grad f(x)|} \in B_r(y)$ so that with the Lipschitz continuity of $\grad f$ and since $y$ is a local minimum
\begin{align*}
	f(y)-f(x) &\le g\Bigl(\frac{|\grad f(x)|}{C_L}\Bigr)-g(0) = \int_0^{\frac{|\grad f(x)|}{C_L}} g'(s)  \, ds \\
	& \le \frac{|\grad f(x)|}{C_L} g'(0) +\frac{|\grad f(x)|^2}{2C_L}= -\frac{|\grad f(x)|^2}{2C_L}.
\end{align*}

